import sys
MOD=998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    vals = data[2:]
    inf = n + 1
    # For each designated position x and each left boundary l,
    # store the smallest right endpoint of a condition with L >= l.
    min_right = [[inf] * (n + 2) for _ in range(n + 1)]
    for i in range(m):
        l, r, x = vals[3 * i:3 * i + 3]
        if r < min_right[x][l]:
            min_right[x][l] = r
    for x in range(1, n + 1):
        row = min_right[x]
        for l in range(n, 0, -1):
            if row[l + 1] < row[l]:
                row[l] = row[l + 1]

    comb = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        comb[i][0] = comb[i][i] = 1
        prev, row = comb[i - 1] if i else [], comb[i]
        for j in range(1, i):
            row[j] = (comb[i - 1][j - 1] + prev[j]) % MOD

    dp = [[0] * (n + 2) for _ in range(n + 2)]
    for i in range(1, n + 2):
        dp[i][i - 1] = 1

    for length in range(1, n + 1):
        c_row = comb[length - 1]
        for l in range(1, n - length + 2):
            r = l + length - 1
            forbidden = min_right
            total = 0
            for k in range(l, r + 1):
                if forbidden[k][l] <= r:
                    continue
                total += c_row[k - l] * dp[l][k - 1] * dp[k + 1][r]
            dp[l][r] = total % MOD
    print(dp[1][n])

