import sys

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:return
    n,q=data[:2]; it=2
    parent=list(range(n)); size=[1]*n; left=list(range(n)); right=list(range(n)); col=list(range(1,n+1)); cnt=[0]+[1]*n
    def find(x):
        while parent[x]!=x:
            parent[x]=parent[parent[x]]
            x=parent[x]
        return x
    out=[]
    for _ in range(q):
        t=data[it]; it+=1
        if t==1:
            x=data[it]-1; c=data[it+1]; it+=2
            r=find(x); old=col[r]
            if old!=c:
                cnt[old]-=size[r]; cnt[c]+=size[r]; col[r]=c
            while left[r]>0:
                a=find(left[r]-1)
                if col[a]!=c: break
                parent[a]=r; size[r]+=size[a]; left[r]=left[a]
            while right[r]<n-1:
                a=find(right[r]+1)
                if col[a]!=c: break
                parent[a]=r; size[r]+=size[a]; right[r]=right[a]
        else:
            c=data[it]; it+=1; out.append(str(cnt[c]))
