from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = [[] for _ in range(n + 1)]
        m = len(conflictingPairs)

        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, idx))

        count = [0] * (n + 1)
        ids_at_left = [[] for _ in range(n + 1)]
        largest = second = 0
        valid_without_removal = 0
        gain = [0] * m

        for right in range(1, n + 1):
            for left, idx in by_right[right]:
                ids_at_left[left].append(idx)
                count[left] += 1
                if left > largest:
                    second = largest
                    largest = left
                elif left == largest:
                    second = largest
                elif left > second:
                    second = left

            valid_without_removal += right - largest
            if largest and count[largest] == 1:
                idx = ids_at_left[largest][0]
                gain[idx] += largest - second

        return valid_without_removal + max(gain)

