from typing import List
class Solution:
 def maxSubarrays(self,n:int,conflictingPairs:List[List[int]])->int:
  by=[[] for _ in range(n+1)]
  m=len(conflictingPairs)
  for i,(a,b) in enumerate(conflictingPairs):
   if a>b:a,b=b,a
   by[b].append((a,i))
  cnt=[0]*(n+1); ids=[[] for _ in range(n+1)]
  top=sec=0
  base=0; gain=[0]*m
  for r in range(1,n+1):
   for l,i in by[r]:
    ids[l].append(i); cnt[l]+=1
    if l>top: sec=top; top=l
    elif l==top: sec=top
    elif l>sec: sec=l
   base += r-top
   if top and cnt[top]==1:
    gain[ids[top][0]] += top-sec
  return base+max(gain)

