import sys
import math


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    items = []

    for i in range(n):
        a, p, b, q = data[2 + 4 * i: 6 + 4 * i]
        g = math.gcd(a, b)
        # Enumerate counts of the less cost-effective machine. A full
        # exchange of these counts can be replaced by equal capacity
        # from the more cost-effective machine.
        if p * b <= q * a:
            items.append((a, p, b, q, a // g, 0))
        else:
            items.append((a, p, b, q, b // g, 1))

    def feasible(target):
        total_cost = 0
        for a, p, b, q, limit, mode in items:
            best = 10**30
            if mode == 0:
                for y in range(limit):
                    rem = target - b * y
                    x = (rem + a - 1) // a if rem > 0 else 0
                    cost = x * p + y * q
                    if cost < best:
                        best = cost
            else:
                for x in range(limit):
                    rem = target - a * x
                    y = (rem + b - 1) // b if rem > 0 else 0
                    cost = x * p + y * q
                    if cost < best:
                        best = cost
            total_cost += best
            if total_cost > budget:
                return False
        return True

    high = min(min(budget * a // p, budget * b // q)
               for a, p, b, q, _, _ in items) + 1
    low = 0
    while low + 1 < high:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)


if __name__ == '__main__':
    main()

