class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # depth[t] is the number of popcount operations needed to reach 1.
        depth = [0] * (n + 1)
        for t in range(2, n + 1):
            x = t
            steps = 0
            while x != 1:
                x = x.bit_count()
                steps += 1
            depth[t] = steps

        # For an integer with popcount t, one operation reaches t;
        # it is reducible within k operations when depth[t] <= k - 1.
        valid_weights = [t for t in range(1, n + 1) if depth[t] <= k - 1]

        # Binomial coefficients modulo MOD.
        choose = [[0] * (n + 1) for _ in range(n + 1)]
        choose[0][0] = 1
        for i in range(1, n + 1):
            choose[i][0] = choose[i][i] = 1
            for j in range(1, i):
                choose[i][j] = (choose[i - 1][j - 1] + choose[i - 1][j]) % MOD

        # Count numbers smaller than s by fixing the first position where
        # their bit differs from s, then choosing the remaining set bits.
        answer = 0
        used = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = n - i - 1
                for weight in valid_weights:
                    needed = weight - used
                    if 0 <= needed <= remaining:
                        answer += choose[remaining][needed]
                used += 1

        return answer % MOD

