  dirs=[(1,1),(1,-1),(-1,-1),(-1,1)]  # clockwise order
  g=[[array('H',[0])*N for _ in range(4)] for _ in range(2)]
  h=[[array('H',[0])*N for _ in range(4)] for _ in range(2)]
  # Straight segments, indexed by required current value (0 then 2).
