import math

class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        half_len = (n + 1) // 2

        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        # Each entry is the modulo-k contribution of a mirrored digit pair
        # (or the single center digit).
        coeff = []
        for i in range(half_len):
            j = n - 1 - i
            if i == j:
                coeff.append(powers[i])
            else:
                coeff.append((powers[i] + powers[j]) % k)

        # gcd[k, coefficients in the suffix] describes exactly which
        # residues can be formed by the remaining digits.
        suffix_gcd = [k] * (half_len + 1)
        for i in range(half_len - 1, -1, -1):
            suffix_gcd[i] = math.gcd(suffix_gcd[i + 1], coeff[i])

        residue = 0
        first_half = []
        for i, c in enumerate(coeff):
            lowest = 1 if i == 0 else 0
            g = suffix_gcd[i + 1]
            for digit in range(9, lowest - 1, -1):
                new_residue = (residue + digit * c) % k
                if new_residue % g == 0:
                    first_half.append(str(digit))
                    residue = new_residue
                    break

        return ''.join(first_half) + ''.join(first_half[:n // 2][::-1])

