from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        prefix = [0] * (n + 1)
        for i, x in enumerate(nums):
            prefix[i + 1] = prefix[i] + x

        # next_greater[i] marks the first position where the running
        # maximum starting at i changes.
        next_greater = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            next_greater[i] = stack[-1] if stack else n
            stack.append(i)

        levels = n.bit_length()
        jumps = [next_greater + [n]]
        costs = [[0] * (n + 1) for _ in range(levels)]

        # Cost of fully extending one constant-maximum segment.
        for i in range(n):
            end = next_greater[i]
            costs[0][i] = nums[i] * (end - i) - (prefix[end] - prefix[i])

        for level in range(1, levels):
            previous_jump = jumps[-1]
            jumps.append([previous_jump[previous_jump[i]] for i in range(n + 1)])
            previous_cost = costs[level - 1]
            costs[level] = [
                previous_cost[i] + previous_cost[previous_jump[i]]
                for i in range(n + 1)
            ]

        answer = 0
        for left in range(n):
            position = left
            remaining = k

            # Consume as many complete maximum segments as the budget allows.
            for level in range(levels - 1, -1, -1):
                segment_cost = costs[level][position]
                if segment_cost <= remaining:
                    remaining -= segment_cost
                    position = jumps[level][position]

            if position == n:
                right = n - 1
            else:
                # Find the furthest affordable point inside this segment.
                lo, hi = position, next_greater[position] - 1
                while lo < hi:
                    mid = (lo + hi + 1) // 2
                    needed = nums[position] * (mid - position + 1) - (
                        prefix[mid + 1] - prefix[position]
                    )
                    if needed <= remaining:
                        lo = mid
                    else:
                        hi = mid - 1
                right = lo

            answer += right - left + 1

        return answer

