class Solution:
    def makeStringGood(self, s: str) -> int:
        from collections import Counter
        f = [0] * 26
        for ch in s:
            f[ord(ch) - 97] += 1
        n = len(s)
        ans = n
        # For a chosen common positive frequency k, process the alphabet from
        # left to right.  The state is the number of characters carried to
        # the next letter.
        for k in range(1, max(f) + 1):
            dp = {0: 0}
            for i in range(26):
                nd = {}
                for carry, cost in dp.items():
                    for wanted in (0, k):
                        bal = f[i] + carry - wanted
                        if bal < 0:
                            val = cost - bal
                            if nd.get(0, n + 1) > val:
                                nd[0] = val
                        else:
                            # Either discard some surplus or pass it along.
                            base = cost
                            for out in range(bal + 1):
                                val = base + bal
                                if val < nd.get(out, n + 1):
                                    nd[out] = val
                dp = nd
            ans = min(ans, min(dp.values()))
        return ans

