    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        parent = [-1] * n
        order = [0]
        for u in order:
            for v, _ in graph[u]:
                if v != parent[u]:
                    parent[v] = u
                    order.append(v)

        # without_parent[u]: best sum in u's subtree when its parent edge is absent
        # with_parent[u]: best sum when its parent edge is retained
        without_parent = [0] * n
        with_parent = [0] * n

        for u in reversed(order):
            base = 0
            gains = []
            for v, w in graph[u]:
                if parent[v] == u:
                    base += without_parent[v]
                    gains.append(w + with_parent[v] - without_parent[v])

            gains.sort(reverse=True)
            add_without = 0
            add_with = 0
            for i, gain in enumerate(gains):
                if gain <= 0:
                    break
                if i < k:
                    add_without += gain
                if i < k - 1:
                    add_with += gain

            without_parent[u] = base + add_without
            with_parent[u] = base + add_with

        return without_parent[0]

