import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]
    a.sort()
    k = n // 2
    pref = [0] * (n + 1)
    for i, x in enumerate(a):
        pref[i + 1] = pref[i] + x

    if n % 2 == 0:
        ans = pref[n] - 2 * pref[k]
    else:
        ans = 0
        # A lone element can only be at an odd (1-based) position:
        # all removed pairs before it account for an even number of positions.
        for i in range(0, n, 2):
            if i < k:
                score = (pref[n] - pref[k + 1]) - (pref[k + 1] - a[i])
            elif i == k:
                score = (pref[n] - pref[k + 1]) - pref[k]
            else:
                score = (pref[n] - pref[k] - a[i]) - pref[k]
            if score > ans:
                ans = score
    print(ans)

