from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(t):
            if not t:
                return list(range(n + 1))
            m = len(t)
            lps = [0] * m
            k = 0
            for i in range(1, m):
                while k and t[i] != t[k]:
                    k = lps[k - 1]
                if t[i] == t[k]:
                    k += 1
                lps[i] = k
            out = []
            k = 0
            for i, ch in enumerate(s):
                while k and ch != t[k]:
                    k = lps[k - 1]
                if ch == t[k]:
                    k += 1
                if k == m:
                    out.append(i - m + 1)
                    k = lps[k - 1]
            return out

        aa, bb, cc = occurrences(a), occurrences(b), occurrences(c)
        ans = n + 1
        for x in aa:
            i = bisect_left(bb, x + len(a))
            if i == len(bb):
                continue
            y = bb[i]
            j = bisect_left(cc, y + len(b))
            if j == len(cc):
                continue
            ans = min(ans, cc[j] + len(c) - x)
        return -1 if ans == n + 1 else ans

