from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        # Generate the postorder traversal iteratively to avoid recursion limits.
        postorder = []
        stack = [(0, False)]
        while stack:
            v, exiting = stack.pop()
            if exiting:
                postorder.append(v)
            else:
                stack.append((v, True))
                for child in reversed(children[v]):
                    stack.append((child, False))

        end = [0] * n
        subtree_size = [1] * n
        for i, v in enumerate(postorder):
            end[v] = i
            if parent[v] != -1:
                subtree_size[parent[v]] += subtree_size[v]

        traversal = ''.join(s[v] for v in postorder)

        # Manacher radii for odd- and even-length palindromes.
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            radius = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - radius >= 0 and i + radius < n and traversal[i - radius] == traversal[i + radius]:
                radius += 1
            odd[i] = radius
            if i + radius - 1 > right:
                left, right = i - radius + 1, i + radius - 1

        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            radius = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - radius - 1 >= 0 and i + radius < n and traversal[i - radius - 1] == traversal[i + radius]:
                radius += 1
            even[i] = radius
            if i + radius - 1 > right:
                left, right = i - radius, i + radius - 1

        answer = [False] * n
        for v in range(n):
            r = end[v]
            length = subtree_size[v]
            l = r - length + 1
            if length % 2:
                answer[v] = odd[(l + r) // 2] >= length // 2 + 1
            else:
                answer[v] = even[(l + r + 1) // 2] >= length // 2
        return answer

