import sys
from functools import lru_cache

MOD = 998244353

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    s = data[1].strip()
    whites = [i for i, c in enumerate(s) if c == 'W']
    blacks = [i for i, c in enumerate(s) if c == 'B']
    # Enumerate the white-to-black bijections. Track which cuts are crossed
    # by at least one backward (B-before-W) edge.
    all_cuts = (1 << (2*n-1)) - 1
    @lru_cache(None)
    def go(k, used, covered):
        if k == n:
            return int(covered == all_cuts)
        w = whites[k]
        ans = 0
        for j, b in enumerate(blacks):
            if not (used >> j) & 1:
                new = covered
                if b < w:
                    new |= ((1 << (w-b)) - 1) << b
                ans += go(k+1, used | (1 << j), new)
        return ans
    print(go(0, 0, 0) % MOD)

if __name__ == '__main__':
    main()

