class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        # Prefix sums at indices with the same remainder modulo k form
        # subarrays whose lengths are divisible by k.
        min_prefix = [None] * k
        min_prefix[0] = 0
        prefix = 0
        best = -10**30

        for j, value in enumerate(nums, 1):
            prefix += value
            r = j % k
            previous_min = min_prefix[r]
            if previous_min is not None:
                best = max(best, prefix - previous_min)
                if prefix < previous_min:
                    min_prefix[r] = prefix
            else:
                min_prefix[r] = prefix

        return best

