class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        mod = 10**9 + 7
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1

        for _ in range(t):
            nxt = [0] * 26
            for i in range(25):
                nxt[i + 1] = cnt[i]
            # Each 'z' produces both 'a' and 'b'.
            nxt[0] = cnt[25]
            nxt[1] = (nxt[1] + cnt[25]) % mod
            cnt = nxt

        return sum(cnt) % mod

