class Solution:
    def minOperations(self, n: int, m: int) -> int:
        import heapq

        digits = len(str(n))
        low = 10 ** (digits - 1)
        high = 10 ** digits - 1

        is_prime = [True] * (high + 1)
        is_prime[0] = False
        if high >= 1:
            is_prime[1] = False
        for p in range(2, int(high ** 0.5) + 1):
            if is_prime[p]:
                for multiple in range(p * p, high + 1, p):
                    is_prime[multiple] = False

        if is_prime[n] or is_prime[m]:
            return -1

        places = [10 ** i for i in range(digits)]
        distances = {n: n}  # The starting value is included in the total cost.
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if distances.get(value) != cost:
                continue
            if value == m:
                return cost

            for place in places:
                digit = (value // place) % 10
                for change in (-1, 1):
                    new_digit = digit + change
                    if not 0 <= new_digit <= 9:
                        continue
                    neighbor = value + change * place
                    if neighbor < low or neighbor > high or is_prime[neighbor]:
                        continue
                    new_cost = cost + neighbor
                    if new_cost < distances.get(neighbor, float('inf')):
                        distances[neighbor] = new_cost
                        heapq.heappush(heap, (new_cost, neighbor))

        return -1

